import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Grid,
  Button,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  CircularProgress,
  Alert,
} from "@mui/material";
import {
  PlayArrow as EvaluateIcon,
  Code as CodeIcon,
} from "@mui/icons-material";
import { ruleEngineAPI } from "../services/api";

const SAMPLE_DATA = {
  TRANSACTION: {
    entityId: "txn-123",
    amount: 15000.0,
    accountBalance: 5000.0,
    type: "debit",
    paymentMethod: "card",
    timestamp: "2025-10-25T10:30:00Z",
  },
  KYC: {
    entityId: "user-456",
    verifiedStatus: false,
    documentType: "passport",
    documentNumber: "A1234567",
    issueDate: "2020-01-15",
    expiryDate: "2030-01-15",
  },
  LOAN: {
    entityId: "loan-789",
    amount: 75000.0,
    interestRate: 8.5,
    termMonths: 36,
    applicantIncome: 50000.0,
    creditScore: 650,
  },
  CREDIT: {
    entityId: "credit-101",
    score: 580,
    historyLength: 24,
    utilizationRate: 0.85,
    latePayments: 3,
    inquiries: 5,
  },
  REPAYMENT: {
    entityId: "repay-202",
    isLate: true,
    daysPastDue: 15,
    amount: 2500.0,
    originalDueDate: "2025-10-10",
    currentBalance: 10000.0,
  },
};

const DataEvaluationPanel = ({ onShowSnackbar }) => {
  const [loading, setLoading] = useState(false);
  const [testData, setTestData] = useState("");
  const [dataType, setDataType] = useState("TRANSACTION");
  const [error, setError] = useState(null);
  const [dataTypes, setDataTypes] = useState([]);

  useEffect(() => {
    const loadDataTypes = async () => {
      try {
        const response = await ruleEngineAPI.getAllDataTypes();
        setDataTypes(response.data || []);
        if (response.data && response.data.length > 0) {
          setDataType(response.data[0].name);
        }
      } catch (error) {
        console.error("Failed to load data types:", error);
      }
    };
    loadDataTypes();
  }, []);

  const handleLoadSample = () => {
    setTestData(
      JSON.stringify(SAMPLE_DATA[dataType] || SAMPLE_DATA.TRANSACTION, null, 2)
    );
  };

  const handleEvaluate = async () => {
    if (!testData.trim()) {
      onShowSnackbar("Test data is required", "error");
      return;
    }

    let facts;
    try {
      facts = JSON.parse(testData);
      if (!Array.isArray(facts)) {
        facts = [facts];
      }
    } catch (e) {
      onShowSnackbar("Invalid JSON format", "error");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      let response;
      switch (dataType) {
        case "TRANSACTION":
          response = await ruleEngineAPI.evaluateTransaction(facts);
          break;
        case "KYC":
          response = await ruleEngineAPI.evaluateKYC(facts);
          break;
        case "LOAN":
          response = await ruleEngineAPI.evaluateLoan(facts);
          break;
        case "CREDIT":
          response = await ruleEngineAPI.evaluateCredit(facts);
          break;
        case "REPAYMENT":
          response = await ruleEngineAPI.evaluateRepayment(facts);
          break;
        default:
          response = await ruleEngineAPI.evaluateGeneric(dataType, facts);
      }

      onShowSnackbar("Evaluation completed successfully", "success");
    } catch (error) {
      setError(error.message);
      onShowSnackbar("Evaluation failed: " + error.message, "error");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 3 }}>
        <Typography
          variant='h4'
          sx={{ fontWeight: "bold", color: "#424242", mb: 1 }}
        >
          Data Evaluation
        </Typography>
        <Typography variant='body1' color='text.secondary'>
          Test data against active fraud detection rules.
        </Typography>
      </Box>

      <Grid container spacing={3}>
        {/* Input Panel */}
        <Grid item xs={12}>
          <Paper sx={{ p: 3, height: "100%" }}>
            <Typography variant='h6' sx={{ mb: 2, fontWeight: "bold" }}>
              Input Data
            </Typography>

            <FormControl fullWidth sx={{ mb: 2 }}>
              <InputLabel>Data Type</InputLabel>
              <Select
                value={dataType}
                onChange={(e) => setDataType(e.target.value)}
                label='Data Type'
              >
                {dataTypes.filter(dt => dt.status === 'ACTIVE').map((dt) => (
                  <MenuItem key={dt.id} value={dt.name}>
                    {dt.displayName || dt.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <Box sx={{ mb: 2 }}>
              <Button
                variant='outlined'
                startIcon={<CodeIcon />}
                onClick={handleLoadSample}
                fullWidth
              >
                Load Sample Data
              </Button>
            </Box>

            <TextField
              fullWidth
              label='Test Data (JSON)'
              multiline
              rows={15}
              value={testData}
              onChange={(e) => setTestData(e.target.value)}
              placeholder='Enter JSON test data...'
              sx={{
                "& .MuiInputBase-input": {
                  fontFamily: "monospace",
                  fontSize: "0.875rem",
                },
              }}
            />

            <Box sx={{ mt: 2 }}>
              <Button
                variant='contained'
                startIcon={<EvaluateIcon />}
                onClick={handleEvaluate}
                disabled={loading || !testData.trim()}
                fullWidth
                sx={{ bgcolor: "#ff9800", "&:hover": { bgcolor: "#f57c00" } }}
              >
                {loading ? <CircularProgress size={20} /> : "Evaluate Data"}
              </Button>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default DataEvaluationPanel;
